<template><div class="page-container"><el-table :data="tableData" border stripe v-loading="loading"><el-table-column prop="leadName" label="线索名称"/><el-table-column prop="company" label="公司"/><el-table-column prop="phone" label="电话"/><el-table-column prop="source" label="来源"/><el-table-column label="状态" width="80"><template #default="{row}"><el-tag :type="row.status===0?'primary':'success'" size="small">{{row.status===0?'新线索':'已转化'}}</el-tag></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" layout="total,prev,pager,next" @current-change="fetchData" style="margin-top:16px"/></div></template>
<script setup>import {ref,onMounted}from 'vue';import {listLeads}from '@/api/crm';const loading=ref(false);const tableData=ref([]);const total=ref(0);const page=ref(1);onMounted(()=>fetchData());async function fetchData(){loading.value=true;try{const res=await listLeads({page:page.value});tableData.value=res.data.records;total.value=res.data.total}finally{loading.value=false}}</script>
